    async def fetch_time(self, params={}) -> Int:
        """
        fetches the current integer timestamp in milliseconds from the exchange server

        https://btsecom.github.io/docs/spotV3_3/en/#query-server-time

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns int: the current integer timestamp in milliseconds from the exchange server
        """
        response = await self.publicGetSpotApiV33Time(params)
        #
        #     {
        #         "iso": "2026-02-06T11:48:37.976Z",
        #         "epoch": 1770378517
        #     }
        #
        return self.safe_timestamp(response, 'epoch')

    async def fetch_markets(self, params={}) -> list[Market]:
        """
        retrieves data on all markets for btse

        https://docs.btse.com/markets/rest/get-markets/

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict[]: an array of objects representing market data
        """
        if self.options['adjustForTimeDifference'] is True:
            await self.load_time_difference()
        response = await self.publicGetPublicApiMarketV1Markets(params)
        data = self.safe_dict(response, 'data', {})
        markets = self.safe_list(data, 'symbols', [])
        return self.parse_markets(markets)

    def parse_market(self, market: dict) -> Market:
        #
        # spot
        #     {
        #         "symbol": "BTC-USDT",
        #         "type": "Spot",
        #         "category": "CRYPTO",
        #         "tradeCurrency": "BTC",
        #         "baseCurrency": "BTC",
        #         "quoteCurrency": "USDT",
        #         "displayName": "Bitcoin",
        #         "active": True,
        #         "minOrderPrice": "0.1",
        #         "minPriceIncrement": "0.1",
        #         "pricePrecision": 1,
        #         "minOrderSize": "0.00001",
        #         "maxOrderSize": "100",
        #         "minSizeIncrement": "0.00001",
        #         "sizePrecision": 5
        #     }
        #
        # swap
        #     {
        #         "symbol": "BTC-PERP-USDT",
        #         "type": "FuturesPerpetual",
        #         "category": "CRYPTO",
        #         "tradeCurrency": "BTC-PERP",
        #         "baseCurrency": "BTC",
        #         "quoteCurrency": "USDT",
        #         "displayName": "Bitcoin",
        #         "active": True,
        #         "minOrderPrice": "0.1",
        #         "minPriceIncrement": "0.1",
        #         "pricePrecision": 1,
        #         "minOrderSize": "1",
        #         "maxOrderSize": "7500000",
        #         "minSizeIncrement": "1",
        #         "sizePrecision": 0,
        #         "contractSize": "0.00001",
        #         "availableSettlement": ["USD", "USDT"]
        #     }
        #
        # future
        #     {
        #         "symbol": "BTC-260925-USDT",
        #         "type": "FuturesTimeBased",
        #         "category": "CRYPTO",
        #         "tradeCurrency": "BTC-260925",
        #         "baseCurrency": "BTC",
        #         "quoteCurrency": "USDT",
        #         "displayName": "Bitcoin",
        #         "active": True,
        #         "minOrderPrice": "0.1",
        #         "minPriceIncrement": "0.1",
        #         "pricePrecision": 1,
        #         "minOrderSize": "1",
        #         "maxOrderSize": "100000",
        #         "minSizeIncrement": "1",
        #         "sizePrecision": 0,
        #         "contractSize": "0.00001",
        #         "availableSettlement": ["USD", "USDT"],
        #         "contractStartTime": 1774569600000,
        #         "contractEndTime": 1790323230000,
        #         "matchingStartTime": 1774569615000,
        #         "becomeInactiveTime": 1790323200000
        #     }
        #
        marketType = self.safe_string(market, 'type')
        isSpot = marketType == 'Spot'
        isFuture = marketType == 'FuturesTimeBased'
        isSwap = marketType == 'FuturesPerpetual'
        id = self.safe_string(market, 'symbol')
        baseId = self.safe_string(market, 'baseCurrency')
        quoteId = self.safe_string(market, 'quoteCurrency')
        base = self.safe_currency_code(baseId)
        quote = self.safe_currency_code(quoteId)
        symbol = base + '/' + quote
        maxAmountString = self.safe_string(market, 'maxOrderSize')
        minAmountString = self.safe_string(market, 'minOrderSize')
        minPriceString = self.safe_string(market, 'minOrderPrice')
        pricePrecision = self.safe_string(market, 'minPriceIncrement')
        amountPrecision = self.safe_string(market, 'minSizeIncrement')
        active = self.safe_bool(market, 'active')
        type = 'spot'
        expiry = None
        contractSize = None
        if not isSpot:
            symbol += ':' + quote
            contractSize = self.safe_string(market, 'contractSize')
            if isFuture:
                expiry = self.safe_integer(market, 'contractEndTime')
                symbol += '-' + self.yymmdd(expiry)
                type = 'future'
            else:
                type = 'swap'
        fees = self.safe_value(self.fees, 'contract')
        if isSpot:
            fees = self.safe_value(self.fees, 'spot')
        return self.safe_market_structure({
            'id': id,
            'symbol': symbol,
            'base': base,
            'quote': quote,
            'settle': None if isSpot else quote,
            'baseId': baseId,
            'quoteId': quoteId,
            'settleId': None if isSpot else quoteId,
            'type': type,
            'spot': isSpot,
            'margin': False if isSpot else None,
            'swap': isSwap,
            'future': isFuture,
            'option': False,
            'active': active,
            'contract': isSwap or isFuture,
            'linear': None if isSpot else True,
            'inverse': None if isSpot else False,
            'taker': fees['taker'],
            'maker': fees['maker'],
            'contractSize': self.parse_number(contractSize),
            'expiry': expiry,
            'expiryDatetime': self.iso8601(expiry),
            'strike': None,
            'optionType': None,
            'precision': {
                'amount': self.parse_number(amountPrecision),
                'price': self.parse_number(pricePrecision),
            },
            'limits': {
                'leverage': {
                    'min': None,
                    'max': None,
                },
                'amount': {
                    'min': self.parse_number(minAmountString),
                    'max': self.parse_number(maxAmountString),
                },
                'price': {
                    'min': self.parse_number(minPriceString),
                    'max': None,
                },
                'cost': {
                    'min': None,
                    'max': None,
                },
            },
            'created': None,
            'info': market,
        })

    async def fetch_ohlcv(self, symbol: str, timeframe='1m', since: Int = None, limit: Int = None, params={}) -> list[list]:
        """
        fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market

        https://docs.btse.com/markets/rest/get-klines/

        :param str symbol: unified symbol of the market to fetch OHLCV data for
        :param str timeframe: the length of time each candle represents
        :param int [since]: timestamp in ms of the earliest candle to fetch
        :param int [limit]: the maximum amount of candles to fetch(default and max 300)
        :param dict [params]: extra parameters specific to the bitteam api endpoint
        :param int [params.until]: timestamp in ms of the latest candle to fetch
        :param boolean [params.paginate]: default False, when True will automatically paginate by calling self endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
        :returns int[][]: A list of candles ordered, open, high, low, close, volume
        """
        await self.load_markets()
        maxLimit = 300
        paginate = False
        paginate, params = self.handle_option_and_params(params, 'fetchOHLCV', 'paginate')
        if paginate:
            return self.fetch_paginated_call_deterministic('fetchOHLCV', symbol, since, limit, timeframe, params, maxLimit)
        market = self.market(symbol)
        interval = self.safe_string(self.timeframes, timeframe, timeframe)
        request = {
            'symbol': market['id'],
            'resolution': interval,
        }
        if limit is not None:
            request['limit'] = min(limit, maxLimit)
        else:
            # the endpoint returns only 10 candles when the limit is omitted
            request['limit'] = maxLimit
        if since is not None:
            # the endpoint accepts timestamps in seconds
            request['start'] = self.parse_to_int(since / 1000)
        until = None
        until, params = self.handle_option_and_params(params, 'fetchOHLCV', 'until')
        if until is not None:
            if since is not None:
                # check if the requested time range is too large for one request
                # if so, just omit until for correct paginated calls for not to get an error from the exchange
                duration = self.parse_timeframe(timeframe)
                maxDelta = duration * maxLimit * 1000  # parseTimeframe returns seconds, the difference below is in milliseconds
                difference = until - since
                if difference < maxDelta:
                    request['end'] = self.parse_to_int(until / 1000)
            else:
                request['end'] = self.parse_to_int(until / 1000)
        response = await self.publicGetPublicApiMarketV1Klines(self.extend(request, params))
        #
        #     {
        #         "data": [
        #             [
        #                 "1786600800",
        #                 "1895.78",
        #                 "1898.52",
        #                 "1892.05",
        #                 "1898.3",
        #                 "560622.306372"
        #             ]
        #         ],
        #         "code": 1,
        #         "msg": "Success",
        #         "success": True,
        #         "time": 1786604274378
        #     }
        #
        data = self.safe_list(response, 'data', [])
        result = self.parse_ohlcvs(data, market, timeframe, since, limit)
        return result

    def parse_ohlcv(self, ohlcv: object, market: Market = None) -> list:
        #
        #     [
        #         "1786600800",  # timestamp in seconds
        #         "1895.78",
        #         "1898.52",
        #         "1892.05",
        #         "1898.3",
        #         "560622.306372"  # volume in quote currency, contract rows may use scientific notation
        #     ]
        #
        return [
            self.safe_timestamp(ohlcv, 0),
            self.safe_number(ohlcv, 1),
            self.safe_number(ohlcv, 2),
            self.safe_number(ohlcv, 3),
            self.safe_number(ohlcv, 4),
            self.safe_number(ohlcv, 5),
        ]

    async def fetch_order_book(self, symbol: str, limit: Int = None, params={}) -> OrderBook:
        """
        fetches information on open orders with bid(buy) and ask(sell) prices, volumes and other data

        https://docs.btse.com/markets/rest/get-orderbook/

        :param str symbol: unified symbol of the market to fetch the order book for
        :param int [limit]: the maximum amount of order book entries to return
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: A dictionary of `order book structures <https://github.com/ccxt/ccxt/wiki/Manual#order-book-structure>` indexed by market symbols
        """
        await self.load_markets()
        market = self.market(symbol)
        request = {
            'symbol': market['id'],
        }
        if limit is not None:
            request['depth'] = min(limit, 50)  # the endpoint supports a maximum depth of 50
        response = await self.publicGetPublicApiMarketV1Orderbook(self.extend(request, params))
        #
        #     {
        #         "data": {
        #             "timestamp": 1786605670799,
        #             "bids": [
        #                 ["1896.11", "0.015"]
        #             ],
        #             "asks": [
        #                 ["1896.74", "0.945"]
        #             ]
        #         },
        #         "code": 1,
        #         "msg": "Success",
        #         "success": True,
        #         "time": 1786605670833
        #     }
        #
        data = self.safe_dict(response, 'data', {})
        timestamp = self.safe_integer(data, 'timestamp')
        return self.parse_order_book(data, market['symbol'], timestamp, 'bids', 'asks')

    async def fetch_funding_rate_history(self, symbol: Str = None, since: Int = None, limit: Int = None, params={}) -> list[FundingRateHistory]:
        """
        fetches historical funding rate prices

        https://docs.btse.com/markets/rest/get-funding-rate-history/

        :param str symbol: unified symbol of the market to fetch the funding rate history for
        :param int [since]: timestamp in ms of the earliest funding rate to fetch, used to select the requested period and then applied client-side
        :param int [limit]: the maximum amount of entries to fetch, applied client-side
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str [params.period]: the funding rate history period, one of '7D', '2W' or '1M', selected from since by default
        :param int [params.until]: timestamp in ms of the latest funding rate to fetch, applied client-side
        :returns dict[]: a list of `funding rate structures <https://docs.ccxt.com/?id=funding-rate-history-structure>`
        """
        if symbol is None:
            raise ArgumentsRequired(self.id + ' fetchFundingRateHistory() requires a symbol argument')
        await self.load_markets()
        market = self.market(symbol)
        if market['contract'] is not True:
            raise BadRequest(self.id + ' fetchFundingRateHistory() supports contract markets only')
        period = None
        period, params = self.handle_option_and_params(params, 'fetchFundingRateHistory', 'period')
        if period is None:
            period = '7D'
            if since is not None:
                age = self.milliseconds() - since
                day = 86400000
                if age > 14 * day:
                    period = '1M'
                elif age > 7 * day:
                    period = '2W'
        request = {
            'symbol': market['id'],
            'period': period,
        }
        until = None
        until, params = self.handle_option_and_params(params, 'fetchFundingRateHistory', 'until')
        response = await self.publicGetPublicApiMarketV1RecentFundingHistory(self.extend(request, params))
        #
        #     {
        #         "data": [
        #             {
        #                 "timestamp": 1786003200911,
        #                 "rate": "0.0000152"
        #             }
        #         ],
        #         "code": 1,
        #         "msg": "Success",
        #         "success": True,
        #         "time": 1786607775380
        #     }
        #
        data = self.safe_list(response, 'data', [])
        rates = self.parse_funding_rate_histories(data, market, since, limit)
        if until is None:
            return rates
        result = []
        for i in range(0, len(rates)):
            rate = rates[i]
            timestamp = self.safe_integer(rate, 'timestamp')
            if (timestamp is None) or (timestamp <= until):
                result.append(rate)
        return result

    def parse_funding_rate_history(self, contract: object, market: Market = None):
        #
        #     {
        #         "timestamp": 1786003200911,
        #         "rate": "0.0000152"
        #     }
        #
        timestamp = self.safe_integer(contract, 'timestamp')
        return {
            'info': contract,
            'symbol': self.safe_symbol(None, market),
            'fundingRate': self.safe_number(contract, 'rate'),
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
        }

    async def fetch_balance(self, params={}) -> Balances:
        """
        query for balance and get the amount of funds available for trading or funds locked in orders

        https://docs.btse.com/wallet/rest/get-user-assets/
        https://btsecom.github.io/docs/futuresV2_3/en/#query-wallet-balance

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str [params.type]: wallet type, spot or swap, default is spot
        :param str [params.wallet]: futures wallet name, CROSS@ by default, or ISOLATED@ followed by the market id with -USDT appended
        :returns dict: a `balance structure <https://docs.ccxt.com/?id=balance-structure>`
        """
        await self.load_markets()
        type = 'spot'
        type, params = self.handle_market_type_and_params('fetchBalance', None, params, type)
        response = None
        if type == 'spot':
            walletResponse = await self.privateGetPublicApiWalletV1UserAssets(params)
            #
            #     {
            #         "data": [
            #             {
            #                 "asset": "BTC",
            #                 "type": "CRYPTO",
            #                 "totalAmount": "100.0",
            #                 "availableAmount": "100.0",
            #                 "availableActions": ["CONVERT", "TRANSFER", "WITHDRAW", "DEPOSIT", "SEND_TO"],
            #                 "cryptoNetwork": {"depositNetworks": ["BITCOIN"], "withdrawalNetworks": ["BITCOIN"]}
            #             }
            #         ],
            #         "code": 1,
            #         "msg": "Success",
            #         "success": True,
            #         "time": 1624989977940
            #     }
            #
            response = self.safe_list(walletResponse, 'data', [])
        else:
            wallet = None
            wallet, params = self.handle_option_and_params(params, 'fetchBalance', 'wallet', 'CROSS@')
            request = {
                'wallet': wallet,
            }
            response = await self.privateGetFuturesApiV23UserWallet(self.extend(request, params))
            #
            #     [
            #         {
            #             "wallet": "CROSS@",
            #             "totalValue": 100,
            #             "marginBalance": 100,
            #             "availableBalance": 100,
            #             "unrealisedProfitLoss": 0,
            #             "assets": [
            #                 {"balance": 0.20183537, "assetPrice": 7158.844999999999, "currency": "BTC"}
            #             ],
            #             "assetsInUse": [
            #                 {"balance": 0.01, "assetPrice": 7158.844999999999, "currency": "BTC"}
            #             ]
            #         }
            #     ]
            #
        return self.parse_balance(response)

    def parse_balance(self, response: object) -> Balances:
        result = {
            'info': response,
        }
        totals = {}
        frees = {}
        useds = {}
        for i in range(0, len(response)):
            row = response[i]
            assets = self.safe_list(row, 'assets')
            if assets is not None:
                # futures wallet row: per-currency totals in assets, locked amounts in assetsInUse
                # several wallet rows can report the same currency, so amounts are aggregated
                inUse = self.safe_list(row, 'assetsInUse', [])
                for j in range(0, len(inUse)):
                    usedRow = inUse[j]
                    usedCode = self.safe_currency_code(self.safe_string(usedRow, 'currency'))
                    if usedCode is None:
                        continue
                    useds[usedCode] = Precise.string_add(self.safe_string(useds, usedCode, '0'), self.safe_string(usedRow, 'balance'))
                for j in range(0, len(assets)):
                    assetRow = assets[j]
                    code = self.safe_currency_code(self.safe_string(assetRow, 'currency'))
                    if code is None:
                        continue
                    totals[code] = Precise.string_add(self.safe_string(totals, code, '0'), self.safe_string(assetRow, 'balance'))
                    useds[code] = self.safe_string(useds, code, '0')
            else:
                # unified wallet row: {"asset": "BTC", "totalAmount": "100.0", "availableAmount": "100.0"}
                # legacy spot wallet row: {"available": 520.52, "currency": "USD", "total": 5566.5566}
                code = self.safe_currency_code(self.safe_string_2(row, 'asset', 'currency'))
                if code is None:
                    continue
                totals[code] = Precise.string_add(self.safe_string(totals, code, '0'), self.safe_string_2(row, 'totalAmount', 'total'))
                frees[code] = Precise.string_add(self.safe_string(frees, code, '0'), self.safe_string_2(row, 'availableAmount', 'available'))
        codes = list(totals.keys())
        for i in range(0, len(codes)):
            code = codes[i]
            account = self.account()
            account['total'] = self.safe_string(totals, code)
            account['free'] = self.safe_string(frees, code)
            account['used'] = self.safe_string(useds, code)
            result[code] = account
        return self.safe_balance(result)

    async def fetch_leverage_tiers(self, symbols: Strings = None, params={}) -> LeverageTiers:
        """

        https://docs.btse.com/markets/rest/get-market-risk-limits/

        retrieve information on the maximum leverage, for different trade sizes
        :param str[]|None symbols: a list of unified market symbols
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a dictionary of `leverage tiers structures <https://docs.ccxt.com/?id=leverage-tiers-structure>`, indexed by market symbols
        """
        await self.load_markets()
        symbols = self.market_symbols(symbols)
        request = {}
        if symbols is not None:
            length = len(symbols)
            if length == 1:
                requestedSymbol = self.safe_string(symbols, 0)
                market = self.market(requestedSymbol)
                request['symbol'] = market['id']
        response = await self.publicGetPublicApiMarketV1RiskLimits(self.extend(request, params))
        #
        #     {
        #         "data": [
        #             {
        #                 "symbol": "BTC-PERP-USDT",
        #                 "riskLimits": [
        #                     {"level": 1, "value": 3000000},
        #                     {"level": 2, "value": 6000000}
        #                 ]
        #             }
        #         ],
        #         "code": 1,
        #         "msg": "Success",
        #         "success": True,
        #         "time": 1786609503920
        #     }
        #
        # a single-symbol request returns the entry directly in data
        #
        data = self.safe_list(response, 'data')
        if data is None:
            single = self.safe_dict(response, 'data', {})
            data = [single]
        result = {}
        for i in range(0, len(data)):
            entry = data[i]
            marketId = self.safe_string(entry, 'symbol')
            market = self.safe_market(marketId)
            symbol = market['symbol']
            if symbols is None or self.in_array(symbol, symbols):
                levels = self.safe_list(entry, 'riskLimits', [])
                tiers = []
                for j in range(0, len(levels)):
                    level = levels[j]
                    # the endpoint only reports the notional ladder, the
                    # per-tier leverage and margin rates are not available
                    tiers.append({
                        'tier': self.safe_integer(level, 'level'),
                        'symbol': symbol,
                        'currency': market['settle'],
                        'minNotional': None,
                        'maxNotional': self.safe_number(level, 'value'),
                        'maintenanceMarginRate': None,
                        'maxLeverage': None,
                        'info': level,
                    })
                result[symbol] = tiers  # rows arrive ordered by level ascending, avoid sortBy which compares numeric keys lexicographically in some transpiled runtimes
        # the exchange only provides the cap of each risk tier, so the floor
        # is derived from the previous tier: 0 for the first tier, and the
        # previous tier's maxNotional for every subsequent tier
        symbolKeys = list(result.keys())
        for i in range(0, len(symbolKeys)):
            symbolKey = symbolKeys[i]
            tiersList = result[symbolKey]
            for j in range(0, len(tiersList)):
                if j == 0:
                    tiersList[j]['minNotional'] = 0
                else:
                    tiersList[j]['minNotional'] = tiersList[j - 1]['maxNotional']
            # php copies arrays by value, so the mutated list must be written back explicitly
            result[symbolKey] = tiersList
        return result

    async def fetch_market_leverage_tiers(self, symbol: str, params={}) -> list[LeverageTier]:
        """
        retrieve information on the maximum leverage, for different trade sizes for a single market

        https://docs.btse.com/markets/rest/get-market-risk-limits/

        :param str symbol: unified market symbol
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a `leverage tiers structure <https://docs.ccxt.com/?id=leverage-tiers-structure>`
        """
        await self.load_markets()
        market = self.market(symbol)
        if market['contract'] is not True:
            raise BadRequest(self.id + ' fetchMarketLeverageTiers() supports contract markets only')
        result = await self.fetch_leverage_tiers([symbol], params)
        return result[symbol]

    async def fetch_tickers(self, symbols: Strings = None, params={}) -> Tickers:
        """

        https://docs.btse.com/markets/rest/get-24-hr-ticker/

        fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market
        :param str[]|None symbols: unified symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a dictionary of `ticker structures <https://docs.ccxt.com/?id=ticker-structure>`
        """
        await self.load_markets()
        symbols = self.market_symbols(symbols, None, True, True)
        # the unified endpoint serves all market types in one call, the legacy type param is accepted and ignored
        params = self.omit(params, 'type')
        response = await self.publicGetPublicApiMarketV1Ticker24hr(params)
        data = self.safe_list(response, 'data', [])
        return self.parse_tickers(data, symbols)

    async def fetch_ticker(self, symbol: str, params={}) -> Ticker:
        """
        fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific market

        https://docs.btse.com/markets/rest/get-24-hr-ticker/

        :param str symbol: unified symbol of the market to fetch the ticker for
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a `ticker structure <https://docs.ccxt.com/?id=ticker-structure>`
        """
        await self.load_markets()
        market = self.market(symbol)
        request = {
            'symbol': market['id'],
        }
        response = await self.publicGetPublicApiMarketV1Ticker24hr(self.extend(request, params))
        #
        #     {
        #         "data": [
        #             {
        #                 "symbol": "BTC-PERP-USDT",
        #                 "lastPrice": "63790.1",
        #                 "openPrice": "63808.3",
        #                 "highPrice": "64446.7",
        #                 "lowPrice": "63289.7",
        #                 "amount": "789198764",
        #                 "volume": "502595131.844331",
        #                 "openTime": 1786514400,
        #                 "closeTime": 1786602644,
        #                 "priceChange": "-18.2",
        #                 "priceChangePercent": "0",
        #                 "prevClosePrice": "63842.4",
        #                 "bidPrice": "63790",
        #                 "bidQty": "222000",
        #                 "askPrice": "63790.2",
        #                 "askQty": "255355",
        #                 "openInterest": "29489680",
        #                 "fundingRate": "0.0001",
        #                 "nextFundingTime": 1786608000000,
        #                 "fundingIntervalMinutes": 480
        #             }
        #         ],
        #         "code": 1,
        #         "msg": "Success",
        #         "success": True,
        #         "time": 1786602644221
        #     }
        #
        # a single-symbol query returns data object, a multi-symbol or bare query returns an array
        data = self.safe_dict(response, 'data')
        if data is None:
            rows = self.safe_list(response, 'data', [])
            data = self.safe_dict(rows, 0, {})
        return self.parse_ticker(data, market)

    def parse_ticker(self, ticker: dict, market: Market = None) -> Ticker:
        #
        # spot rows carry the fields up to askQty, contract rows additionally carry
        # openInterest, fundingRate, nextFundingTime and fundingIntervalMinutes
        #
        marketId = self.safe_string(ticker, 'symbol')
        market = self.safe_market(marketId, market)
        last = self.safe_string(ticker, 'lastPrice')
        baseVolume = self.safe_string(ticker, 'amount')
        if (baseVolume is not None) and (market is not None) and (market['contract'] is True):
            # for contract markets the amount field is denominated in contracts, verified live -
            # scaling by contractSize converts it into base currency units
            contractSizeString = self.number_to_string(market['contractSize'])
            if contractSizeString is not None:
                baseVolume = Precise.string_mul(baseVolume, contractSizeString)
        timestamp = self.safe_timestamp(ticker, 'closeTime')
        return self.safe_ticker({
            'symbol': self.safe_symbol(marketId, market),
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'high': self.safe_string(ticker, 'highPrice'),
            'low': self.safe_string(ticker, 'lowPrice'),
            'bid': self.safe_string(ticker, 'bidPrice'),
            'bidVolume': self.safe_string(ticker, 'bidQty'),
            'ask': self.safe_string(ticker, 'askPrice'),
            'askVolume': self.safe_string(ticker, 'askQty'),
            'vwap': None,
            'open': self.safe_string(ticker, 'openPrice'),
            'close': last,
            'last': last,
            'previousClose': self.safe_string(ticker, 'prevClosePrice'),
            'change': self.safe_string(ticker, 'priceChange'),
            # priceChangePercent is a ratio rounded to three decimals, not a percentage,
            # so it is left out and safeTicker derives percentage from change and open
            'percentage': None,
            'average': None,
            'baseVolume': baseVolume,
            'quoteVolume': self.safe_string(ticker, 'volume'),
            'markPrice': None,
            'indexPrice': None,
            'info': ticker,
        }, market)

    async def fetch_open_interest(self, symbol: str, params={}):
        """
        Retrieves the open interest of a derivative trading pair

        https://docs.btse.com/markets/rest/get-24-hr-ticker/

        :param str symbol: Unified CCXT market symbol
        :param dict [params]: exchange specific parameters
        :returns dict} an open interest structure{@link https://docs.ccxt.com/?id=interest-history-structure:
        """
        await self.load_markets()
        market = self.market(symbol)
        if market['spot'] is True:
            raise BadRequest(self.id + ' fetchOpenInterest() symbol does not support market ' + symbol)
        request = {
            'symbol': market['id'],
        }
        response = await self.publicGetPublicApiMarketV1Ticker24hr(self.extend(request, params))
        interest = self.safe_dict(response, 'data')
        if interest is None:
            rows = self.safe_list(response, 'data', [])
            interest = self.safe_dict(rows, 0, {})
        return self.parse_open_interest(interest, market)

    async def fetch_open_interests(self, symbols: Strings = None, params={}):
        """
        Retrieves the open interest for a list of symbols

        https://docs.btse.com/markets/rest/get-24-hr-ticker/

        :param str[] [symbols]: a list of unified CCXT market symbols
        :param dict [params]: exchange specific parameters
        :returns dict[]: a list of `open interest structures <https://docs.ccxt.com/?id=open-interest-structure>`
        """
        await self.load_markets()
        symbols = self.market_symbols(symbols)
        response = await self.publicGetPublicApiMarketV1Ticker24hr(params)
        data = self.safe_list(response, 'data', [])
        rows = []
        for i in range(0, len(data)):
            row = data[i]
            # spot rows do not carry an open interest
            if self.safe_string(row, 'openInterest') is not None:
                rows.append(row)
        return self.parse_open_interests(rows, symbols)

    def parse_open_interest(self, interest: object, market: Market = None):
        #
        # ticker/24hr contract rows, see parseFundingRate for the full shape
        #
        marketId = self.safe_string(interest, 'symbol')
        market = self.safe_market(marketId, market)
        timestamp = self.safe_timestamp(interest, 'closeTime')
        return self.safe_open_interest({
            'symbol': market['symbol'],
            'openInterestAmount': self.safe_number(interest, 'openInterest'),
            'openInterestValue': self.safe_number(interest, 'openInterestUSD'),
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'info': interest,
        }, market)

