    def parse_funding_rate(self, contract: object, market: Market = None) -> FundingRate:
        #
        # ticker/24hr contract rows
        #     {
        #         "symbol": "ETH-PERP-USDT",
        #         "lastPrice": "1896.17",
        #         "openPrice": "1887.07",
        #         "highPrice": "1924",
        #         "lowPrice": "1872.44",
        #         "amount": "1937140691",
        #         "volume": "366459222.269293",
        #         "openTime": 1786518000,
        #         "closeTime": 1786607054,
        #         "priceChange": "9.1",
        #         "priceChangePercent": "0.005",
        #         "prevClosePrice": "1897.71",
        #         "bidPrice": "1896",
        #         "bidQty": "105",
        #         "askPrice": "1896.01",
        #         "askQty": "11354",
        #         "openInterest": "19344237",
        #         "fundingRate": "0.00006016",
        #         "nextFundingTime": 1786608000000,
        #         "fundingIntervalMinutes": 480
        #     }
        #
        marketId = self.safe_string(contract, 'symbol')
        market = self.safe_market(marketId, market)
        timestamp = self.safe_timestamp(contract, 'closeTime')
        # dated futures carry a zero nextFundingTime only applies to
        # perpetuals, observed live, the zero means no next funding and is omitted
        nextFundingTimestamp = self.safe_integer_omit_zero(contract, 'nextFundingTime')
        fundingIntervalMinutes = self.safe_integer(contract, 'fundingIntervalMinutes')
        interval = None
        if fundingIntervalMinutes is not None:
            hours = self.parse_to_int(fundingIntervalMinutes / 60)
            interval = str(hours) + 'h'
        return {
            'info': contract,
            'symbol': market['symbol'],
            'markPrice': None,
            'indexPrice': None,
            'interestRate': None,
            'estimatedSettlePrice': None,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'fundingRate': self.safe_number(contract, 'fundingRate'),
            'fundingTimestamp': None,
            'fundingDatetime': None,
            'nextFundingRate': None,
            'nextFundingTimestamp': nextFundingTimestamp,
            'nextFundingDatetime': self.iso8601(nextFundingTimestamp),
            'previousFundingRate': None,
            'previousFundingTimestamp': None,
            'previousFundingDatetime': None,
            'interval': interval,
        }

    async def fetch_trades(self, symbol: str, since: Int = None, limit: Int = None, params={}) -> list[Trade]:
        """
        get the list of most recent trades for a particular symbol

        https://docs.btse.com/markets/rest/get-trades/

        :param str symbol: unified symbol of the market to fetch trades for
        :param int [since]: timestamp in ms of the earliest trade to fetch, applied client-side to the most recent trades window
        :param int [limit]: the maximum amount of trades to fetch(max 500)
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param int [params.until]: timestamp in ms of the latest entry to fetch, applied client-side to the most recent trades window
        :returns Trade[]: a list of `trade structures <https://docs.ccxt.com/?id=public-trades>`
        """
        await self.load_markets()
        market = self.market(symbol)
        request = {
            'symbol': market['id'],
        }
        if limit is not None:
            request['limit'] = min(limit, 500)  # the endpoint supports a maximum of 500 trades
        # the unified trades endpoint has no server-side time filtering, since and until are applied client-side below
        until = None
        until, params = self.handle_option_and_params(params, 'fetchTrades', 'until')
        response = await self.publicGetPublicApiMarketV1Trades(self.extend(request, params))
        #
        #     {
        #         "data": [
        #             {
        #                 "id": 91151062,
        #                 "timestamp": 1786605669577,
        #                 "price": "1896.3291755587",
        #                 "size": "0.06",
        #                 "quoteSize": "113.7797505335",
        #                 "side": "BUY"
        #             }
        #         ],
        #         "code": 1,
        #         "msg": "Success",
        #         "success": True,
        #         "time": 1786605671650
        #     }
        #
        data = self.safe_list(response, 'data', [])
        trades = self.parse_trades(data, market, since, limit)
        if until is None:
            return trades
        result = []
        for i in range(0, len(trades)):
            trade = trades[i]
            timestamp = self.safe_integer(trade, 'timestamp')
            if (timestamp is None) or (timestamp <= until):
                result.append(trade)
        return result

    async def fetch_my_trades(self, symbol: Str = None, since: Int = None, limit: Int = None, params={}) -> list[Trade]:
        """
        fetch all trades made by the user

        https://docs.btse.com/spot/rest/get-trade-history/
        https://docs.btse.com/futures/rest/get-trade-history/

        :param str [symbol]: unified market symbol
        :param int [since]: the earliest time in ms to fetch trades for
        :param int [limit]: the maximum number of trades structures to retrieve
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param int [params.until]: timestamp in ms for the ending date filter, default is None
        :param str [params.type]: 'spot' or 'swap' or 'future', default is 'spot'
        :returns dict[]: a list of `trade structures <https://docs.ccxt.com/#/?id=trade-structure>`
        """
        await self.load_markets()
        paginate = self.safe_bool(params, 'paginate', False)
        if paginate is True:
            params = self.omit(params, 'paginate')
            return await self.fetch_paginated_call_dynamic('fetchMyTrades', symbol, since, limit, params)
        market = None
        request = {}
        if symbol is not None:
            market = self.market(symbol)
            request['symbol'] = market['id']
        if since is not None:
            request['startTime'] = since
        if limit is not None:
            request['count'] = limit
        request, params = self.handle_until_option('endTime', request, params)
        marketType = 'spot'
        marketType, params = self.handle_market_type_and_params('fetchMyTrades', market, params, marketType)
        response = None
        if marketType == 'spot':
            if symbol is None:
                raise ArgumentsRequired(self.id + ' fetchMyTrades() requires a symbol argument for spot markets')
            #
            #     {
            #         "data": [
            #             {
            #                 "serialId": 375599088,
            #                 "tradeId": "de1a79b8-f408-4e05-b8b7-7ed3c4e86542",
            #                 "orderId": "6c72d906-cb8f-469c-8ab0-b97bc8dff9c2",
            #                 "clOrderId": null,
            #                 "symbol": "BTC-USD",
            #                 "base": "BTC",
            #                 "quote": "USD",
            #                 "orderSide": "BUY",
            #                 "orderType": 77,
            #                 "triggerType": 0,
            #                 "triggerPrice": 0,
            #                 "price": 64235.97008,
            #                 "size": 1.9,
            #                 "filledSize": 0.00002,
            #                 "feeCurrency": "BTC",
            #                 "feeAmount": 1e-8,
            #                 "timestamp": 1784890959551
            #             }
            #         ],
            #         "code": 1,
            #         "msg": "Success",
            #         "success": True,
            #         "time": 1786610160164
            #     }
            #
            response = await self.privateGetSpotApiV4TradeTradeHistory(self.extend(request, params))
        else:
            # the futures endpoint does not support a count parameter, the limit is applied client-side
            request = self.omit(request, 'count')
            if market is not None:
                request['symbol'] = self.futures_request_id(market)
            #
            #     {
            #         "data": [
            #             {
            #                 "tradeId": "1ad38104-6248-4a45-bc56-5fa9bf7f3868",
            #                 "orderId": "8ad94105-8cce-4e01-86b8-2d0fb403db66",
            #                 "clOrderId": "",
            #                 "positionId": "BTC-PERP-USDT",
            #                 "orderSide": "BUY",
            #                 "type": 77,
            #                 "orderDetailType": null,
            #                 "price": 0,
            #                 "size": 1,
            #                 "avgFilledPrice": 60010,
            #                 "filledSize": 1,
            #                 "triggerPrice": 0,
            #                 "contractSize": 0.00001,
            #                 "base": "BTC",
            #                 "quote": "USDT",
            #                 "symbol": "BTC-PERP",
            #                 "wallet": "BTC-PERP Isolated Wallet",
            #                 "feeCurrency": "USDT",
            #                 "feeAmount": 0.00012002,
            #                 "realizedPnl": 0,
            #                 "total": -0.00012002,
            #                 "serialId": 375598162,
            #                 "timestamp": 1784882344446
            #             }
            #         ],
            #         "code": 1,
            #         "msg": "Success",
            #         "success": True,
            #         "time": 1786610160164
            #     }
            #
            response = await self.privateGetFuturesApiV3TradeTradeHistory(self.extend(request, params))
        rows = self.safe_list(response, 'data')
        if rows is None:
            rows = response
        return self.parse_trades(rows, market, since, limit)

    async def fetch_order_trades(self, id: str, symbol: Str = None, since: Int = None, limit: Int = None, params={}) -> list[Trade]:
        """
        fetch all the trades made from a single order

        https://btsecom.github.io/docs/spotV3_3/en/#query-user-trades-fills
        https://btsecom.github.io/docs/futuresV2_3/en/#query-trades-fills-2

        :param str id: order id
        :param str [symbol]: unified market symbol
        :param int [since]: the earliest time in ms to fetch trades for
        :param int [limit]: the maximum number of trades to retrieve
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str [params.clientOrderId]: client order id, could be used instead of the order id
        :param str [params.type]: 'spot' or 'swap' or 'future', default is 'spot'
        :returns dict[]: a list of `trade structures <https://docs.ccxt.com/?id=trade-structure>`
        """
        await self.load_markets()
        clientOrderId = self.safe_string(params, 'clientOrderId')
        if clientOrderId is None:
            if id is None:
                raise ArgumentsRequired(self.id + ' fetchOrderTrades() requires an id argument or a clientOrderId parameter')
            else:
                params = self.extend(params, {'orderID': id})
        else:
            params = self.extend(params, {'clOrderID': clientOrderId})
        return await self.fetch_my_trades(symbol, since, limit, params)

